namespace WindowsFormsApp1
{
    public partial class Form1 : Form
    {
        public Form1()
        {
            InitializeComponent();
        }
        public static string AuthKey = "432bbb5c234511ad098ad47831c4aa5f";
        private void button1_Click(object sender, EventArgs e)
        {
            string text = RevertString(richTextBox1.Text);
            string[] array = StringSplitBy(text.Substring(0, 1010), 101); // разбили по 101 символу
            array[0].Substring(0, 1);    
            string text2 = array[0].Substring(1);  // первая строка без первого символа
            for (int i = 1; i < 10; i++)              
            {
                text2 += array[i].Substring(1);    // вырезали по первой цифре в каждой строке и слили всё в text2
            }

            string[] array2 = StringSplitBy(text.Substring(1010), 1001);    // разбили по 1001 символу
            // взяли первые 1010 символов, разбили на строки по 101 символ, удалили по первому знаку и слили обратно в строку
            // взяли всё с 1010 символа и разбили по 1001 штуке, вырезали по одному символу
            // и слили всё это к первой строке
            for (int j = 0; j < array2.Length; j++)
            {
                text2 += array2[j].Substring(1);
             //   MessageBox.Show(text2, "text2");
            }
            if (text2.Length % 1000 != 0)
            {
                text2 = text2.Remove(text2.Length - 1);
            }
            byte[] bytes = Convert.FromBase64String(text2);
            richTextBox2.Text = Encoding.UTF8.GetString(bytes);

        }
        public static string RevertString(string str)
        {
            char[] array = str.ToCharArray();
            Array.Reverse(array);
            return new string(array);
        }
        public static string[] StringSplitBy(string str, int num)
        {

            int num2 = (int) Math.Ceiling((float)str.Length / (float)num);
            string[] array = new string[num2];
            for (int i = 0; i < num2; i++)
            {
                int length = num;
                if (i == num2 - 1)
                {
                    length = str.Length - num * (num2 - 1);
                }
                array[i] = str.Substring(i * num, length);
            }
            return array;
        }

        private void button2_Click(object sender, EventArgs e)
        {
            string str = richTextBox2.Text;
            string text = str.Length.ToString();
            object obj = text.ToString().Length.ToString();
            string[] array = StringSplitBy(Convert.ToBase64String(Encoding.UTF8.GetBytes(str)), 1000);
            string[] array2 = StringSplitBy(array[0], 100);
            string text2 = obj.ToString();
            Random rand = new Random();
            for (int i = 0; i < 9; i++)
            {
                text2 += array2[i];
                if (i < text.Length)
                {
                    text2 += text[i].ToString();
                }
                else
                {
                    text2 += rand.Next(9).ToString();
                }
            }
            text2 += array2[9];
            text2 += AuthKey[0].ToString();
            for (int j = 1; j < array.Length; j++)
            {
                text2 += array[j];
                if (j < AuthKey.Length)
                {
                    text2 += AuthKey[j].ToString();
                }
                else
                {
                    text2 += rand.Next(9).ToString();
                }
            }
            richTextBox3.Text = RevertString(text2);
        }

        private void button3_Click(object sender, EventArgs e)
        {
            richTextBox1.Clear();
            richTextBox2.Clear();
            richTextBox3.Clear();
        }
    }
